bad_example:
fn incrementar(contador: &Mutex<i32>) {
    let mut guard = contador.lock().unwrap();
    *guard += 1;
    registrar(contador); // si registrar() tambien hace contador.lock(), deadlock
}

good_example:
fn incrementar(contador: &Mutex<i32>) {
    {
        let mut guard = contador.lock().unwrap();
        *guard += 1;
    } // guard se libera aca, antes de llamar a registrar()
    registrar(contador);
}

